class MysteryGame extends GameEngine{constructor(t,e,s){super(t,"mystery",e),this.prizes=s,this.selected=[],this.matched=0,this.clicks=0}render(t){const e=`\n      <div class="game-container">\n        <div class="game-header">\n          <h2>🎁 Hộp Bí Ẩn</h2>\n          <p>Tìm 3 hộp có cùng giải thưởng</p>\n          <div class="timer" id="timer">0s</div>\n        </div>\n\n        <div class="mystery-game">\n          <div class="mystery-boxes" id="mysteryBoxes">\n            ${this.prizes.map((t,e)=>`\n              <div class="mystery-box" data-index="${e}" onclick="selectMysteryBox(this, ${e})">\n                <div class="mystery-box-inner">\n                  <div class="mystery-box-back">?</div>\n                  <div class="mystery-box-front" style="color: ${t.color||"#8b5cf6"}">\n                    <div class="mystery-box-emoji">${t.icon||"🎁"}</div>\n                    <div class="mystery-box-name">${t.name}</div>\n                  </div>\n                </div>\n              </div>\n            `).join("")}\n          </div>\n\n          <div class="mystery-stats">\n            <div class="stat-item">\n              <div class="stat-label">Trúng Tìm</div>\n              <div class="stat-value" id="matchCount">0</div>\n            </div>\n            <div class="stat-item">\n              <div class="stat-label">Tổng Chọn</div>\n              <div class="stat-value" id="totalClicks">0</div>\n            </div>\n          </div>\n        </div>\n      </div>\n    `;document.getElementById(t).innerHTML=e,this.startTimer()}attachEventListeners(){}selectBox(t,e){if(!(t.classList.contains("found")||this.selected.length>=2||t.classList.contains("flipped"))&&(t.classList.add("flipped"),this.selected.push(e),this.clicks++,document.getElementById("totalClicks").textContent=this.clicks,2===this.selected.length)){const[t,e]=this.selected,s=document.querySelector(`[data-index="${t}"]`),n=document.querySelector(`[data-index="${e}"]`),i=this.prizes[t].name===this.prizes[e].name;setTimeout(()=>{i?(s.classList.add("found"),n.classList.add("found"),this.matched+=2,document.getElementById("matchCount").textContent=this.matched,this.matched===this.prizes.length&&this.endGame(0)):(s.classList.remove("flipped"),n.classList.remove("flipped")),this.selected=[]},600)}}endGame(t){this.state="completed";const e=this.prizes[t||0];this.selectedPrize=e;const s=this.getCompletionTime();fetch("/api/game/result",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({session_code:this.sessionCode,game_type:this.gameType,prize_id:e.id,completion_time:s,extra_data:{clicks:this.clicks,matched:this.matched}})}).catch(t=>{}),this.showResultScreen(e)}showResultScreen(t){const e=t.color||"#8b5cf6",s=`\n      <div class="result-screen">\n        <div class="result-emoji" style="color: ${e}">🎉</div>\n        <h2 class="result-title">Chúc Mừng!</h2>\n        <p class="result-message">Bạn đã hoàn thành trò chơi</p>\n        \n        <div class="result-detail">\n          <div style="font-size: 2.5rem; margin-bottom: 10px;">${t.icon||"🎁"}</div>\n          <strong style="color: ${e}; font-size: 1.4rem;">${t.name}</strong>\n          ${t.cash_amount?`<p>💰 ${t.cash_amount.toLocaleString()}đ</p>`:""}\n          <p style="font-size: 0.9rem; opacity: 0.8;">Lần nhấp: <strong>${this.clicks}</strong></p>\n        </div>\n\n        <div class="result-buttons">\n          <button class="btn btn-primary" onclick="location.href='/thank-you'">\n            ✅ Nhận Thưởng\n          </button>\n          <button class="btn btn-secondary" onclick="shareResult()">\n            📤 Chia Sẻ\n          </button>\n        </div>\n      </div>\n    `;document.querySelector(".game-container").innerHTML=s}startTimer(){this.startTime=Date.now();const t=setInterval(()=>{const e=Math.floor((Date.now()-this.startTime)/1e3),s=document.getElementById("timer");s?s.textContent=e+"s":clearInterval(t)},1e3)}}function selectMysteryBox(t,e){window.mysteryGameInstance&&window.mysteryGameInstance.selectBox(t,e)}